      signal: t.signal,
      onChunk: (o) => e.postMessage({
        type: "lasso:transform:chunk",
        chunk: o
      })
    }).then(() => {
      t = null, e.postMessage({ type: "lasso:transform:complete" });
    }).catch((o) => {
      t = null, o.name !== "AbortError" && e.postMessage({
